    d = dmod.Daemon(p.base)
    tid = p.db.add_task("tidy", "tidy up", kind="work", tier="light", origin="user")

    def no_space(*a, **k):
        raise OSError(28, "No space left on device")
    monkeypatch.setattr(dmod.subprocess, "Popen", no_space)
    d.dispatch()
    t = p.db.task(tid)
