def test_remote_listener_sends_the_outbox_on_every_reconnect(env, monkeypatch):
    from ttp import cli
    failed = subprocess.CompletedProcess([], 255, "", "ssh: unreachable")
    flushes = iter([failed, None])
    calls = []
    monkeypatch.setattr(cli, "flush_outbox", lambda name, entry, quiet=False: calls.append(("flush", name)) or next(flushes))
    monkeypatch.setattr(cli, "forward", lambda entry, argv, quiet=False: calls.append(("listen", quiet)) or 0)
    monkeypatch.setattr(cli.time, "sleep", lambda s: None)
    assert cli.forward_listen({"host": "box", "dir": "/x"}, ["listen", "demo", "--chat", "c1"], "demo") == 0
    assert calls == [("flush", "demo"), ("flush", "demo"), ("listen", True)]


def _stuck_outbox(cli, outbox, monkeypatch, rc):
    """One queued message that keeps failing with `rc` on a host that is reachable."""
    outbox.add("demo", ["say", "demo", "--", "x"], "id-1", None)
    monkeypatch.setattr(cli, "_send_say", lambda entry, argv, cid, capture=False:
                        subprocess.CompletedProcess(argv, rc, "", "bash: ttp: command not found"))


@pytest.mark.parametrize("rc", [1, 127])
def test_a_stuck_queued_message_does_not_block_forwarded_commands(env, monkeypatch, capsys, rc):
    from ttp import cli, outbox
    from ttp.project import register
    register("demo", {"host": "far", "dir": "/x"})
    monkeypatch.chdir(env["tmp"])
    _stuck_outbox(cli, outbox, monkeypatch, rc)
    ran = []
    monkeypatch.setattr(cli, "forward", lambda entry, argv, quiet=False: ran.append(argv) or 0)
    with pytest.raises(SystemExit) as e:
        cli.need("demo", ["status", "demo"])
    assert e.value.code == 0 and ran == [["status", "demo"]]
    out, err = capsys.readouterr()
    assert "cannot reach" not in err and err.count("stay queued") == 1, err
    assert "1 message(s) queued here for demo" in out
    assert [q["id"] for q in outbox.entries("demo")] == ["id-1"]


def test_a_stuck_queued_message_does_not_keep_the_listener_away(env, monkeypatch, capsys):
    from ttp import cli, outbox
    _stuck_outbox(cli, outbox, monkeypatch, 127)
    results, naps = iter([255, 0]), []
    monkeypatch.setattr(cli, "forward", lambda entry, argv, quiet=False: next(results))
    def nap(s):
        naps.append(s)
        assert len(naps) < 3, "the listener backs off on the stuck message instead of connecting"
    monkeypatch.setattr(cli.time, "sleep", nap)
    assert cli.forward_listen({"host": "far", "dir": "/x"}, ["listen", "demo", "--chat", "c1"], "demo") == 0
    assert naps == [5.0], "it connected, dropped once and reconnected; it did not back off on the stuck message"
    err = capsys.readouterr().err
    assert "cannot reach" not in err and err.count("stay queued") == 1, err
    assert [q["id"] for q in outbox.entries("demo")] == ["id-1"]


def test_say_to_an_older_remote_runtime_resends_without_the_client_id(env, monkeypatch):
    from ttp import cli
    sent = []

    def ssh(entry, argv, capture=False):
        sent.append(argv)
        if any(a.startswith("--client-id") for a in argv):
            return subprocess.CompletedProcess(argv, 2, "", "ttp: error: unrecognized arguments: --client-id=c-1")
        return subprocess.CompletedProcess(argv, 0, "", "")
    monkeypatch.setattr(cli, "_ssh", ssh)
    r = cli._send_say({"host": "far", "dir": "/x"}, ["say", "demo", "--", "hi"], "c-1", capture=True)
    assert r.returncode == 0
    assert sent == [["say", "--client-id=c-1", "demo", "--", "hi"], ["say", "demo", "--", "hi"]]


def _ask(p, text="Option A or B?", **fields):
    from ttp import coordinator as coord
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")   # the kickoff brief, already read
    problems = coord.apply(p, [{"type": "ask_user", "text": text, **fields}])
    return problems, p.db.one("SELECT * FROM messages WHERE kind='ask' ORDER BY id DESC LIMIT 1")


def _legacy_ask(p, rec="use option A", text="Option A or B?", severity="high"):
    """An ask registered with a default before new asks stopped getting one."""
    from ttp import coordinator as coord
    p.db.x("UPDATE messages SET handled=1 WHERE direction='in'")
    mid = p.db.post("out", f"{text}{coord._DEFAULT_NOTE}1h, I will go with the recommendation: {rec}",
                    chat=None, kind="ask", severity=severity)
    p.db.set_kv(coord.ASK_DEFAULTS_KEY, {**p.db.kv(coord.ASK_DEFAULTS_KEY, {}), str(mid): rec})
    return p.db.one("SELECT * FROM messages WHERE id=?", (mid,))


def test_an_ask_needs_a_blocking_reason_and_never_gets_a_default(env):
    p = make(env)
    from ttp import coordinator as coord
    for fields in ({}, {"blocking": "preference"}, {"blocking": ""}):
        problems, ask = _ask(p, **fields)
        assert problems and "`blocking` must be one of" in problems[0], fields
        assert ask is None, "a rejected ask reached the user"
    problems, ask = _ask(p, blocking="access", recommendation="use option A")
    assert problems == [] and ask["text"].startswith("Option A or B?")
    assert p.db.kv(coord.ASK_DEFAULTS_KEY, {}) == {}, "a new ask was registered to fall back on a timer"
    assert coord.expire_asks(p, now=time.time() + 1000 * 3600) == []
    assert f"ask #{ask['id']} (waits for the user)" in coord.digest(p, {}, [], [])
    least = {"least_disruptive": "a canary on one box breaks the no-shared-machines restriction"}
    for reason in coord.BLOCKING_REASONS:
        extra = least if reason == "restriction" else {}
        assert _ask(p, f"Question on {reason}?", blocking=reason, **extra)[0] == [], reason


def test_a_restriction_ask_must_name_the_least_disruptive_way_forward(env):
    p = make(env)
    from ttp import coordinator as coord
    assert "least_disruptive" in coord.ACTIONS_SCHEMA["properties"]["actions"]["items"]["properties"]
    for extra in ({}, {"least_disruptive": "wait"}):
        problems, ask = _ask(p, "May I restart the shared service?", blocking="restriction", **extra)
        assert problems and "first answer what is a reasonably non-disruptive way to proceed" in problems[0]
        assert "put it in least_disruptive with the restriction it breaks" in problems[0]
        assert ask is None, "a restriction ask without the way it considered reached the user"
    way = "restart it during the nightly lull; still breaks 'never restart a shared service'"
    problems, ask = _ask(p, "May I restart the shared service?", blocking="restriction",
                         least_disruptive=way, recommendation="yes, at night")
    assert problems == []
    assert f"Least-disruptive way considered: {way}" in ask["text"] and "My recommendation: yes" in ask["text"]
    problems, _ = _ask(p, "may i restart the shared service?", blocking="restriction", least_disruptive=way)
    assert problems and "already asked" in problems[0], "the note hid a repeated ask"
    # Asks for any other reason need no such field and carry no such line.
    problems, ask = _ask(p, "Grant repo access?", blocking="access", least_disruptive=way)
    assert problems == [] and "Least-disruptive" not in ask["text"]
    problems, ask = _ask(p, "Approve the spend?", blocking="spend")
    assert problems == [] and ask["text"] == "Approve the spend?"


def test_a_blocking_ask_shows_its_recommendation_but_never_applies_it(env):
    p = make(env)
    from ttp import coordinator as coord
    from ttp.web import state_payload
    problems, ask = _ask(p, blocking="spend", recommendation="raise the daily cap to $150")
    assert problems == [] and "My recommendation: raise the daily cap to $150" in ask["text"]
    assert ask["id"] in [m["id"] for m in p.db.unread_for_chat("c1", 0, "info")], "the relay would not show it"
    shown = [m["text"] for m in state_payload(p, p.db)["attention"] if m["id"] == ask["id"]]
    assert shown and "raise the daily cap to $150" in shown[0], "the web app would not show it"
    assert p.db.kv(coord.ASK_DEFAULTS_KEY, {}) == {}
    assert coord.expire_asks(p, now=time.time() + 1000 * 3600) == []
    assert p.db.one("SELECT handled FROM messages WHERE id=?", (ask["id"],))["handled"] == 0
    problems, _ = _ask(p, " option a or b? ", blocking="spend", recommendation="something else")
    assert problems and "already asked" in problems[0]


def test_a_reversible_ask_is_rejected_and_the_rejection_reaches_the_next_digest(env):
    p = make(env)
