    run_dir = tmp_path / "live"
    run_dir.mkdir()
    tid = p.db.add_task("long job", "s", kind="work", tier="light", origin="user")
    p.db.x("INSERT INTO runs(task,role,provider,started,status,dir) VALUES(?,?,?,?,?,?)",
           (tid, "worker", "fake", time.time(), "running", str(run_dir)))
