    (path / "tools" / "build").mkdir(parents=True)
    (path / "tools" / "build" / "CMakeLists.txt").write_text("project(x)\n")
    _git_out(path, "add", ".")
    _git_out(path, *_IDENT, "commit", "-qm", "tools")
