def test_the_disk_guard_alerts_once_per_episode_holds_heavy_tasks_and_resumes(env, monkeypatch):
    import collections
    p = make(env)
    from ttp import coordinator as coord
    from ttp import daemon as dm
    from ttp.web import state_payload
    usage = collections.namedtuple("usage", "total used free")
    free = {"gb": 40}   # a 1000 GB disk: the guard is at 50 GB, and lifts at 60
    monkeypatch.setattr(dm.shutil, "disk_usage", lambda path: usage(1000e9, 0, free["gb"] * 1e9))
    alerts = lambda: p.db.q("SELECT id FROM messages WHERE kind='alert' AND ref='disk'")  # noqa: E731
    code = p.db.add_task("build it", "s", kind="code", tier="light", origin="user")
    ask = p.db.add_task("what fills the disk?", "s", kind="question", tier="light", origin="user")
    d = dm.Daemon(p.base)
    d.dispatch()
    assert p.db.q("SELECT id FROM runs WHERE task=?", (ask,)), "a question was held by the disk guard"
    assert not p.db.q("SELECT id FROM runs WHERE task=?", (code,)), "a code task started on a low disk"
    assert p.db.task(code)["attempts"] == 0
    assert len(alerts()) == 1
    assert "## Disk: 40.0 GB free of 1000.0 GB; LOW" in coord.digest(p, {}, [], [])
    st = state_payload(p, p.db)
    assert st["disk"]["low"] and st["disk"]["free_gb"] == 40.0 and st["disk_low"]
    free["gb"] = 55    # above the threshold, below the resume point: still on, no new alert
    d.dispatch()
    assert p.db.kv("disk_low") and len(alerts()) == 1
    free["gb"] = 45
    dm.Daemon(p.base).dispatch()   # a restart keeps the episode and does not alert again
    assert len(alerts()) == 1
    free["gb"] = 61
    d = dm.Daemon(p.base)
    d.dispatch()
    assert p.db.kv("disk_low") is None and p.db.q("SELECT id FROM runs WHERE task=?", (code,))
    assert "## Disk: 61.0 GB free of 1000.0 GB; ok (guard below 50.0 GB)" in coord.digest(p, {}, [], [])
    free["gb"] = 30
    d.dispatch()
    assert len(alerts()) == 2, "a new episode must alert again"


def test_disk_resume_free_gb_holds_the_guard_until_its_resume_point(env, monkeypatch):
    import collections
    p = make(env)
    from ttp import daemon as dm
    from ttp.project import config_problems
    p.set_config("disk.min_free_gb", 30)
    p.set_config("disk.resume_free_gb", 50)
    usage = collections.namedtuple("usage", "total used free")
    free = {"gb": 29}   # a 10000 GB disk: 5% is 500 GB, so min_free_gb (30) is the threshold
    monkeypatch.setattr(dm.shutil, "disk_usage", lambda path: usage(10000e9, 0, free["gb"] * 1e9))
    alerts = lambda: p.db.q("SELECT id FROM messages WHERE kind='alert' AND ref='disk'")  # noqa: E731
    d = dm.Daemon(p.base)
    d.check_disk()   # trips below min_free_gb
    assert p.db.kv("disk_low") and p.db.kv("disk")["resume_gb"] == 50 and len(alerts()) == 1
    assert "held until 50 GB are free" in p.db.one("SELECT text FROM messages WHERE ref='disk'")["text"]
    for gb in (31, 40, 49.5):   # between min and resume: still held (1.2 times 30 would have let go at 36)
        free["gb"] = gb
        d.check_disk()
        assert p.db.kv("disk_low"), gb
    d = dm.Daemon(p.base)   # a restart keeps the episode: no new alert, still held
    d.check_disk()
    assert p.db.kv("disk_low") and len(alerts()) == 1
    free["gb"] = 50
    d.check_disk()   # released at the resume point
    assert p.db.kv("disk_low") is None
    free["gb"] = 40
    d.check_disk()   # above min_free_gb: not tripped again
    assert p.db.kv("disk_low") is None and len(alerts()) == 1
    assert config_problems(p.raw_config()) == []
    p.set_config("disk.resume_free_gb", 10)   # below min_free_gb: raised to it, with a warning
    assert config_problems(p.raw_config()) == [
        "disk.resume_free_gb: 10 is below disk.min_free_gb 30; the guard's threshold is used instead when it is higher"]
    free["gb"] = 29
    d = dm.Daemon(p.base)
    d.check_disk()
    assert p.db.kv("disk")["resume_gb"] == 30
    free["gb"] = 30
    d.check_disk()
    assert p.db.kv("disk_low") is None


@pytest.mark.parametrize("value, resume_gb", [(40, 40), (500, 7.7)])
def test_disk_resume_free_gb_on_a_small_disk_uses_the_percent_threshold(env, monkeypatch, value, resume_gb):
    import collections
