    assert not _events(p, tid, "deferral_expired")
    old = [lb for lb in _labels(p, tid) if not lb.startswith("deferred_since:")]
    p.db.update_task(tid, labels=old + [f"deferred_since:{time.time() - 15 * 86400:.0f}"])
