    # Re-deferring is a new decision: its own clock.
    assert coord.apply(p, [{"type": "task_update", "id": tid, "start_when": "exit 1"}]) == []
    _settle_deferred(d, tid)
    assert len(_events(p, tid, "deferral_expired")) == 1


