# --- PRs leave draft only with the user's recorded approval ---------------------------------------

HEAD = "a" * 40   # the head commit pr-watch read and the fake gh reports, unless a test moves it

FAKE_GH = '''#!{python}
import os, sys
a = sys.argv[1:]
head = os.environ.get("FAKE_GH_HEAD", "{head}")
if a[:2] == ["alias", "list"]:
    print("rdy: pr ready")
    print("rapi: api $1 --method PATCH")
    sys.exit(0)
if a[:2] == ["pr", "view"]:
    pos = [x for x in a[2:] if not x.startswith("-") and "headRefOid" not in x][:1]
    n = pos[0] if pos and pos[0].isdigit() else "7"
    print(f"https://github.com/acme/widgets/pull/{{n}} {{head}}")
    sys.exit(0)
if a[:2] == ["api", "graphql"] and any("node(id:" in x for x in a):
    print(f"https://github.com/acme/widgets/pull/7 {{head}}")
    sys.exit(0)
if a[:1] == ["api"] and a[-2:] == ["-q", ".head.sha"]:
    print(head)
    sys.exit(0)
with open(os.environ["FAKE_GH_LOG"], "a") as f:
    f.write(" ".join(a) + "\\n")
'''

READY_7 = ("query=mutation{markPullRequestReadyForReview(input:{pullRequestId:\"PR_kwDOabc123\"})"
           "{clientMutationId}}")


def _gh_runner(p, tmp_path, run_dir=None, cwd=None):
    fake = tmp_path / "realbin"
    fake.mkdir(exist_ok=True)
    (fake / "gh").write_text(FAKE_GH.format(python=sys.executable, head=HEAD))
    (fake / "gh").chmod(0o755)
    log = tmp_path / "gh.log"
    log.write_text("")
    env = {**os.environ, "PATH": f"{p.harness / 'bin'}:{fake}:{os.environ['PATH']}", "TTP_PROJECT": str(p.base),
           "TTP_PYTHON": sys.executable, "FAKE_GH_LOG": str(log)}
    env.pop("PYTHONPATH", None)
    env.pop("TTP_RUN_DIR", None)
    if run_dir:
        env["TTP_RUN_DIR"] = str(run_dir)

    def gh(*args, head=None):
        r = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=60, cwd=cwd,
                           env={**env, **({"FAKE_GH_HEAD": head} if head else {})})
        ran = log.read_text().splitlines()
        log.write_text("")
        return r.returncode, r.stderr, ran
    return gh


def _heads_seen(p, *keys, sha=HEAD, seen=0.0):
    """pr-watch read these PRs' head commit `sha` at `seen` (what an approval binds to)."""
    from ttp import prguard
    p.db.set_kv(prguard.HEADS_KEY, {**(p.db.kv(prguard.HEADS_KEY, {}) or {}),
                                    **{k: {"sha": sha, "seen": seen} for k in keys}})


def test_workers_gh_keeps_prs_in_draft_until_the_user_approves(env, tmp_path):
    """A project marked its PRs ready for review on its own. Every run's PATH starts with the
    harness's gh, which refuses that until the user's approval is recorded, for any provider."""
    p = make(env)
    from ttp import coordinator as coord
    gh = _gh_runner(p, tmp_path)
    url = "https://github.com/acme/widgets/pull/7"
    mutation = tmp_path / "ready.graphql"
    mutation.write_text(READY_7.removeprefix("query="))
    _heads_seen(p, "acme/widgets#7")

    refused = [("pr", "create", "--title", "t", "--body", "b"),
               ("rapi", "repos/acme/widgets/pulls/7", "-F", "draft=false"),
               ("api", "graphql", "-F", f"query=@{mutation}"),
               ("pr", "ready", "7"), ("pr", "ready"), ("pr", "ready", url), ("rdy", "7"),
               ("api", "-X", "PATCH", "repos/acme/widgets/pulls/7", "-F", "draft=false"),
               ("api", "repos/acme/widgets/pulls", "-f", "title=t", "-f", "head=b", "-f", "base=main"),
               ("api", "graphql", "-f", READY_7),
               ("api", "graphql", "-f", "query=mutation{createPullRequest(input:{title:\"t\"}){clientMutationId}}")]
    for args in refused:
        rc, err, ran = gh(*args)
        assert rc == 1 and "refused" in err and ran == [], f"gh {' '.join(args)} was let through"
    allowed = [("pr", "create", "--draft", "--title", "t"), ("pr", "create", "-d"), ("pr", "ready", "7", "--undo"),
               ("pr", "list"), ("api", "repos/acme/widgets/pulls", "-F", "draft=true", "-f", "title=t"),
               ("api", "repos/acme/widgets/pulls/7"), ("issue", "list")]
    for args in allowed:
        rc, err, ran = gh(*args)
        assert rc == 0 and ran == [" ".join(args)], f"gh {' '.join(args)} was refused: {err}"

    # The user's yes to a blocking review ask that names the PR is recorded, and lets it out of draft.
    assert coord.apply(p, [{"type": "ask_user", "text": f"Mark {url} ready for review?", "blocking": "review",
                            "recommendation": "yes"}]) == []
    ask = p.db.one("SELECT id FROM messages WHERE kind='ask'")["id"]
    yes = p.db.post("in", "yes, go ahead", chat="web", provenance="web-session")
    # The coordinator sees each user message's id, to name it in pr_approve.
    assert f"[user message #{yes} via" in coord.digest(p, {}, [], [yes])
    # ...and its provenance and whether it can approve a PR, so a web or cli-legacy yes is asked again.
    assert "provenance=web-session, can approve a PR: yes" in coord.digest(p, {}, [], [yes])
    legacy = p.db.post("in", "yes", chat="cli", provenance="cli-legacy")
    assert "provenance=cli-legacy, can approve a PR: no" in coord.digest(p, {}, [], [legacy])
    # The ask never reached Slack, so it cannot back the approval; the user's own message naming the PR can.
    assert "no Slack ts" in " ".join(coord.apply(p, [{"type": "pr_approve", "id": ask, "text": url,
                                                      "quote": "yes, go ahead"}]))
    said = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="web-session")
    assert coord.apply(p, [{"type": "pr_approve", "id": said, "text": url, "quote": "yes"}]) == []
    for n, args in enumerate([("pr", "ready", "7"), ("pr", "ready"), ("rdy", "7"), ("api", "graphql", "-f", READY_7),
                              ("api", "-X", "PATCH", "repos/acme/widgets/pulls/7", "-F", "draft=false")]):
        if n:   # each approval lets the PR out of draft once
            said = p.db.post("in", f"yes, {url} may leave draft again", chat="web", provenance="web-session")
            assert coord.apply(p, [{"type": "pr_approve", "id": said, "text": url, "quote": "yes"}]) == []
        rc, err, ran = gh(*args)
        assert rc == 0 and ran, f"gh {' '.join(args)} was refused after the user approved: {err}"
        rc, err, ran = gh(*args)
        assert rc == 1 and ran == [] and "blocked" in err, f"gh {' '.join(args)} reused a spent approval"
    rc, err, ran = gh("pr", "ready", "8")
    assert rc == 1 and "acme/widgets#8" in err and ran == [], "one PR's approval let another out of draft"
    rc, err, ran = gh("pr", "create", "--title", "t")
    assert rc == 1, "an approval let a PR be opened as non-draft"


def test_pr_approve_needs_the_users_answer_naming_the_pr(env):
    p = make(env)
    from ttp import coordinator as coord, prguard
    url = "https://github.com/acme/widgets/pull/7"

    def approve(msg, pr=url, quote="yes"):
        return coord.apply(p, [{"type": "pr_approve", "id": msg, "text": pr, "quote": quote}])

    _heads_seen(p, "acme/widgets#7", "acme/widgets#9")

    coord.apply(p, [{"type": "ask_user", "text": f"Grant access to the device for {url}?", "blocking": "access",
                     "recommendation": "yes"}])
    access = p.db.one("SELECT id FROM messages WHERE kind='ask' ORDER BY id DESC")["id"]
    coord.apply(p, [{"type": "ask_user", "text": f"Ready {url} for review?", "blocking": "review",
                     "recommendation": "yes"}])
    review = p.db.one("SELECT id FROM messages WHERE kind='ask' ORDER BY id DESC")["id"]
    coord.apply(p, [{"type": "ask_user", "text": "Merge the release PR?", "blocking": "merge",
                     "recommendation": "yes"}])
    vague = p.db.one("SELECT id FROM messages WHERE kind='ask' ORDER BY id DESC")["id"]
    assert "not answered" in " ".join(approve(review)), "approved before the user answered"
    p.db.post("in", "yes", chat="web", provenance="cli-peer")
    assert "blocking review or merge" in " ".join(approve(access))
    assert "does not name" in " ".join(approve(vague))
    assert "names no PR" in " ".join(approve(review, "the big one"))
    note = p.db.post("out", f"Opened {url}", chat=None, kind="alert")
    assert approve(note), "an alert counted as an approval"
    assert not prguard.approved(p.db, "acme/widgets#7")
    assert "no Slack ts" in " ".join(approve(review)), "an ask that never reached Slack backed an approval"
    assert not prguard.approved(p.db, "acme/widgets#7")
    assert approve(p.db.post("in", f"yes, {url}", chat="web", provenance="cli-peer")) == []
    assert prguard.approved(p.db, "acme/widgets#7")
    said = p.db.post("in", "please mark acme/widgets#9 ready for review", chat="web", provenance="web-session")
    assert approve(said, "https://github.com/acme/widgets/pull/9", "mark acme/widgets#9 ready") == []
    assert prguard.approved(p.db, "acme/widgets#9") and not prguard.approved(p.db, "acme/widgets#8")


def test_pr_approve_counts_only_channels_a_run_cannot_write(env):
    """Every message ends up as a row a run could write, so only some channels count as the user's yes."""
    p = make(env)
    from ttp import coordinator as coord, prguard
    url = "https://github.com/acme/widgets/pull/7"
    _heads_seen(p, *(f"acme/widgets#{n}" for n in (7, 8, 9, 10)))
    for prov in (None, "web", "cli-legacy", "system"):
        said = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance=prov)
        out = " ".join(coord.apply(p, [{"type": "pr_approve", "id": said, "text": url, "quote": "ready"}]))
        assert "does not count as the user's approval" in out, prov
        # No Slack here: the refusal says so instead of sending the coordinator to ask on Slack.
        assert "Slack DMs are not set up" in out and "Do not ask again" in out, out
    assert not prguard.approved(p.db, "acme/widgets#7")
    said = p.db.post("in", f"yes, mark {url} ready", chat="web", provenance="cli-legacy")
    try:
        prguard.approve(p.db, url, said, "ready", slack=object())
    except ValueError as e:
        assert "answer on Slack" in str(e) and "not set up" not in str(e), e
    else:
        raise AssertionError("a cli-legacy yes counted as an approval")
    assert not prguard.approved(p.db, "acme/widgets#7")
    # The ask path too: only the user's answers count, and only on an approving channel.
    coord.apply(p, [{"type": "ask_user", "text": f"Ready {url} for review?", "blocking": "review",
                     "recommendation": "yes"}])
    ask = p.db.one("SELECT id FROM messages WHERE kind='ask' ORDER BY id DESC")["id"]
    p.db.post("in", "yes", chat="web", kind="note", provenance="web-session")
    out = " ".join(coord.apply(p, [{"type": "pr_approve", "id": ask, "text": url, "quote": "yes"}]))
    assert "has not answered" in out, "a non-user answer counted as the user's yes"
    coord.apply(p, [{"type": "ask_user", "text": f"Mark {url} ready now?", "blocking": "review",
                     "recommendation": "yes"}])
    ask = p.db.one("SELECT id FROM messages WHERE kind='ask' ORDER BY id DESC")["id"]
    p.db.post("in", "yes", chat="cli", provenance="cli-legacy")
    assert "does not count" in " ".join(coord.apply(p, [{"type": "pr_approve", "id": ask, "text": url,
                                                         "quote": "yes"}]))
    assert not prguard.approved(p.db, "acme/widgets#7")


def test_pr_approve_reads_a_slack_approval_back_from_slack(env, monkeypatch):
    """A row saying it came from Slack is checked against Slack: a forged one (unknown ts, someone else's
    message, other words, an old message) is refused; the user's real answer is recorded with its ts."""
    p = make(env)
    from ttp import coordinator as coord, prguard, slack as slackmod
    sl = _fake_slack()
    fake_call = sl.call

    def call(method, **kw):   # as Slack does for a ts it has no message for
        if method == "conversations.replies" and not any(m["ts"] == kw["ts"] for m in sl.msgs):
            raise slackmod.SlackError(f"{method}: thread_not_found", method, "thread_not_found")
        return fake_call(method, **kw)
    sl.call = call
    monkeypatch.setattr(slackmod, "from_config", lambda cfg: sl)
    url = "https://github.com/acme/widgets/pull/7"
    _heads_seen(p, *(f"acme/widgets#{n}" for n in (7, 8, 9, 10)))

    def approve(msg, pr=url):          # quotes the user's message, or their "yes" to an ask
        row = p.db.one("SELECT direction, text FROM messages WHERE id=?", (msg,))
        quote = row["text"] if row["direction"] == "in" else "yes"
        return " ".join(coord.apply(p, [{"type": "pr_approve", "id": msg, "text": pr, "quote": quote}]))

    def slack_row(text, ts, ref=None):
        return p.db.post("in", text, chat="slack", channel="slack", ref=ref or ts, provenance="slack", ext_id=ts)

    now = time.time()
    sl.msgs += [{"ts": f"{now - 50:.6f}", "user": "U2", "text": f"mark {url} ready"},
                {"ts": f"{now - 40:.6f}", "user": "U1", "text": "demo: what is the status?"},
                {"ts": f"{now - 30:.6f}", "user": "U1", "text": f"demo: mark {url} ready"}]
    assert "Slack has no message" in approve(slack_row(f"mark {url} ready", f"{now - 10:.6f}"))
    assert "not the user's" in approve(slack_row(f"mark {url} ready", f"{now - 50:.6f}"))
    assert "does not match" in approve(slack_row(f"mark {url} ready", f"{now - 40:.6f}"))
    assert "no Slack ts" in approve(p.db.post("in", f"mark {url} ready", chat="slack", channel="slack",
                                              provenance="slack"))
    monkeypatch.setattr(slackmod, "from_config", lambda cfg: None)
    real = slack_row(f"mark {url} ready", f"{now - 30:.6f}")
    assert "not set up" in approve(real)
    monkeypatch.setattr(slackmod, "from_config", lambda cfg: sl)
    assert not prguard.approved(p.db, "acme/widgets#7")
    assert approve(real) == ""
    rec = p.db.kv(prguard.APPROVALS_KEY)["acme/widgets#7"]
    assert rec["channel"] == "slack" and rec["external_id"] == f"{now - 30:.6f}" and rec["answer"] == real

    # An ask is answered on Slack after it: in its thread or the DM, never by an older message (a replayed
    # yes) or a reply in another thread. Review asks reach Slack below slack_min_severity, with their ts.
    from ttp.daemon import Daemon
    d = Daemon(p.base)
    d.cfg["notify"]["slack"] = True
    d._slack = sl

    def asked(text, **kw):
        coord.apply(p, [{"type": "ask_user", "text": text, "blocking": "review", "recommendation": "yes", **kw}])
        d.deliver_outbound()
        return p.db.one("SELECT id, ext_id FROM messages WHERE kind='ask' ORDER BY id DESC")

    def answer(ask, dt, thread=None):
        ts = f"{float(ask['ext_id']) + dt:.6f}"
        sl.msgs.append({"ts": ts, "user": "U1", "text": "yes", **({"thread_ts": thread} if thread else {})})
        slack_row("yes", ts, ref=thread)
        return ts

    ask = asked("Ready acme/widgets#9 for review?", severity="normal")
    assert any(m["ts"] == ask["ext_id"] and m.get("bot_id") for m in sl.msgs), "the review ask missed Slack"
    answer(ask, -0.5)
    assert "older than the ask" in approve(ask["id"], "acme/widgets#9")
    ask = asked("Ready acme/widgets#9 for review now?")
    answer(ask, 0.5, thread=f"{now - 30:.6f}")
    assert "answers another thread" in approve(ask["id"], "acme/widgets#9")
    ask = asked("Mark acme/widgets#9 ready?")
    later = answer(ask, 0.5, thread=ask["ext_id"])
    assert approve(ask["id"], "acme/widgets#9") == ""
    assert p.db.kv(prguard.APPROVALS_KEY)["acme/widgets#9"]["external_id"] == later
    ask = asked("Mark acme/widgets#10 ready?")
    answer(ask, 0.5)                    # a top-level yes in the DM after the ask counts too
    assert approve(ask["id"], "acme/widgets#10") == ""


def test_pr_approve_reads_the_ask_back_from_slack(env, monkeypatch):
    """A run that can write the database could add an ask row before a yes the user gave earlier. The ask
    is read back from Slack by the ts the daemon stored when it posted it: a row with no Slack ts, with an
    old ts, pointing at another post, another project's post or an ask for another PR is refused."""
    p = make(env)
    from ttp import coordinator as coord, prguard, slack as slackmod
    from ttp.daemon import Daemon
    sl = _fake_slack()
    monkeypatch.setattr(slackmod, "from_config", lambda cfg: sl)
    d = Daemon(p.base)
    d.cfg["notify"]["slack"] = True
    d._slack = sl
    url = "https://github.com/acme/widgets/pull/7"
    _heads_seen(p, *(f"acme/widgets#{n}" for n in (7, 8, 9, 10)))

    def approve(msg, pr=url):          # quotes the user's message, or their "yes" to an ask
        row = p.db.one("SELECT direction, text FROM messages WHERE id=?", (msg,))
        quote = row["text"] if row["direction"] == "in" else "yes"
        return " ".join(coord.apply(p, [{"type": "pr_approve", "id": msg, "text": pr, "quote": quote}]))

    def yes(ts, thread=None):          # the user's real yes on Slack, and its row
        sl.msgs.append({"ts": ts, "user": "U1", "text": "yes", **({"thread_ts": thread} if thread else {})})
        return p.db.post("in", "yes", chat="slack", channel="slack", ref=thread or ts, provenance="slack",
                         ext_id=ts)

    def forged(text, ts=None, ext_id=None):
        mid = p.db.post("out", text, chat=None, kind="ask", severity="high", ref="blocking:review")
        p.db.x("UPDATE messages SET ext_id=?, ts=COALESCE(?, ts) WHERE id=?", (ext_id, ts, mid))
        return mid

    t0 = time.time() - 3600
    yes(f"{t0:.6f}")                   # an old yes, given to something else
    # A forged ask with an old ts and no Slack ts, followed by a copy of that old yes.
    ask = forged(f"Ready {url} for review?", ts=t0 - 60)
    p.db.post("in", "yes", chat="slack", channel="slack", ref=f"{t0:.6f}", provenance="slack", ext_id=f"{t0:.6f}")
    assert "no Slack ts" in approve(ask)
    # ...pointing at a Slack ts that has no message, or at the user's own message.
    ask = forged(f"Ready {url} for review?", ext_id=f"{t0 - 60:.6f}")
    yes(f"{t0 + 1:.6f}")
    assert "Slack has no message" in approve(ask)
    ask = forged(f"Ready {url} for review?", ext_id=f"{t0:.6f}")
    yes(f"{t0 + 2:.6f}")
    assert "not sent by this project's bot" in approve(ask)
    # ...at another project's post, or at a post of this project that says something else.
    other = sl.post("other", f"Ready {url} for review?")
    ask = forged(f"Ready {url} for review?", ext_id=other)
    yes(f"{float(other) + 0.5:.6f}", thread=other)
    assert "not posted for this project" in approve(ask)
    coord.apply(p, [{"type": "notify", "text": f"Opened {url}", "severity": "high"}])
    d.deliver_outbound()
    alert = p.db.one("SELECT ext_id FROM messages WHERE kind='alert' ORDER BY id DESC")["ext_id"]
    ask = forged(f"Ready {url} for review?", ext_id=alert)
    yes(f"{float(alert) + 0.5:.6f}", thread=alert)
    assert "does not match" in approve(ask)
    # ...at a real ask for another PR, reworded to name this one.
    coord.apply(p, [{"type": "ask_user", "text": "Ready acme/widgets#8 for review?", "blocking": "review",
                     "recommendation": "yes"}])
    d.deliver_outbound()
    real8 = p.db.one("SELECT id, ext_id FROM messages WHERE kind='ask' ORDER BY id DESC")
    ask = forged(f"Ready {url} for review?", ext_id=real8["ext_id"])
    yes(f"{float(real8['ext_id']) + 0.5:.6f}", thread=real8["ext_id"])
    assert "does not match" in approve(ask)
    assert not prguard.approved(p.db, "acme/widgets#7") and not prguard.approved(p.db, "acme/widgets#8")
    # ...at a real ask for this PR, but answered by a yes from before it.
    coord.apply(p, [{"type": "ask_user", "text": f"Ready {url} for review now? Tests & CI are green (<1 h old).",
                     "blocking": "review",
                     "recommendation": "yes"}])
    d.deliver_outbound()
    real7 = p.db.one("SELECT id, ext_id, text FROM messages WHERE kind='ask' ORDER BY id DESC")
    ask = forged(real7["text"], ts=t0 - 60, ext_id=real7["ext_id"])
    p.db.post("in", "yes", chat="slack", channel="slack", ref=f"{t0:.6f}", provenance="slack", ext_id=f"{t0:.6f}")
    assert "older than the ask" in approve(ask)
    assert not prguard.approved(p.db, "acme/widgets#7")
    # A real ask, as Slack returns it (links in <>, &, < and > escaped), backs the user's yes after it.
    coord.apply(p, [{"type": "ask_user", "text": f"Mark {url} ready? Tests & CI are green (<1 h old).",
                     "blocking": "review", "recommendation": "yes"}])
    d.deliver_outbound()
    real7 = p.db.one("SELECT id, ext_id, text FROM messages WHERE kind='ask' ORDER BY id DESC")
    post = next(m for m in sl.msgs if m["ts"] == real7["ext_id"])
    escaped = real7["text"].replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    post["text"] = f"[{p.name}] " + escaped.replace(url, f"<{url}>")
    yes(f"{float(real7['ext_id']) + 0.5:.6f}", thread=real7["ext_id"])
    assert approve(real7["id"]) == "", "the user's yes to the real ask was refused"
    assert prguard.approved(p.db, "acme/widgets#7") and not prguard.approved(p.db, "acme/widgets#8")


def test_inbound_messages_carry_the_channel_they_came_in_on(env, tmp_path, monkeypatch):
    from ttp import cli
    from ttp.db import DB
    p = make(env)
    cli.main(["say", "demo", "--", "hello"])
    said = p.db.one("SELECT provenance FROM messages WHERE direction='in' ORDER BY id DESC LIMIT 1")
    assert said["provenance"] == "cli-legacy"
    d, sl, poll = _slack_daemon(p)
    sl.msgs.append({"ts": f"{time.time() + 1:.6f}", "user": "U1", "text": "demo: from slack"})
    poll()
    got = p.db.one("SELECT provenance, ext_id FROM messages WHERE channel='slack' ORDER BY id DESC LIMIT 1")
    assert got == {"provenance": "slack", "ext_id": sl.msgs[-1]["ts"]}
    # A database from before provenance gets the columns, and older inbound messages get theirs.
    old = tmp_path / "old.db"
    con = sqlite3.connect(old)
    con.executescript("CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL NOT NULL, "
                      "direction TEXT NOT NULL, chat TEXT, channel TEXT NOT NULL DEFAULT 'chat', "
                      "kind TEXT NOT NULL DEFAULT 'user', severity TEXT NOT NULL DEFAULT 'normal', "
                      "text TEXT NOT NULL, ref TEXT, handled INTEGER NOT NULL DEFAULT 0);"
                      "INSERT INTO messages(ts,direction,channel,text,ref) VALUES (1,'in','slack','a','1.5'),"
                      "(2,'in','web','b',NULL),(3,'in','chat','c',NULL),(4,'out','chat','d',NULL);")
    con.commit()
    con.close()
    rows = DB(old).q("SELECT provenance, ext_id FROM messages ORDER BY id")
    assert rows == [{"provenance": "slack", "ext_id": "1.5"}, {"provenance": "web", "ext_id": None},
                    {"provenance": "cli-legacy", "ext_id": None}, {"provenance": None, "ext_id": None}]


def test_claude_hook_denies_ways_around_the_gh_guard(env, monkeypatch, tmp_path):
    from ttp import hook
    from ttp.providers import get_provider
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))

    def denied(cmd):
        out, _ = hook.pre_tool_use({"tool_name": "Bash", "tool_input": {"command": cmd}})
        return bool(out) and out["hookSpecificOutput"]["permissionDecision"] == "deny"

    for cmd in ("/usr/bin/gh pr ready 7", "cd x && ~/bin/gh api graphql -f query=q", "\\gh pr create -t t",
                "curl -X PATCH -H 'Authorization: token x' https://api.github.com/repos/a/b/pulls/7 -d '{\"draft\":false}'",
                "curl https://api.github.com/graphql -d '{\"query\":\"mutation{markPullRequestReadyForReview}\"}'",
                "python3 -c \"import requests; requests.post('https://api.github.com/repos/a/b/pulls')\""):
        assert denied(cmd), cmd
    for cmd in ("gh pr ready 7", "gh pr create --draft", "git status", "ls /usr/bin/gh", "gh api repos/a/b/pulls",
                "curl https://api.github.com/repos/a/b", "grep -rn draft=false tests/"):
        assert not denied(cmd), cmd
    worker, _ = get_provider("claude").build(role="worker", model="opus", effort="low", cwd=".", budget_usd=None,
                                             read_only=False, schema=None, restrictions={})
    pre = json.loads(worker[worker.index("--settings") + 1])["hooks"]["PreToolUse"][0]
    assert pre["matcher"] == "Bash" and pre["hooks"][0]["command"].endswith("ttp.hook PreToolUse")


def test_prompts_say_only_the_user_takes_a_pr_out_of_draft():
    prompts = RUNTIME.parent / "template" / "prompts"
    for name in ("kind-code.md", "kind-review.md"):
        text = " ".join((prompts / name).read_text().split())
        assert "NEVER mark a PR ready for review" in text and "only the user takes a PR out of draft" in text, name
    coord_text = " ".join((prompts / "coordinator.md").read_text().split())
    assert "A PR leaves draft ONLY on the user's explicit yes" in coord_text and "`pr_approve`" in coord_text
    worker = " ".join((prompts / "worker.md").read_text().split())
    assert "NEVER mark a PR ready for review or open one that is not a draft" in worker
    for name in ("worker.md", "kind-code.md", "kind-review.md"):
        assert "hand off `blocked` with the PR's URL in `pr`" in " ".join((prompts / name).read_text().split()), name
    assert "`ttp checks`" in " ".join((prompts / "kind-code.md").read_text().split())
    # The order: review, findings cleared, ask the user, pr_approve with their words, then gh pr ready.
    order = ["independent `review` task passes", "pr-watch reports it clean", "ask_user (blocking `review`)",
             "`pr_approve` it with their words in `quote`", "a worker runs `gh pr ready`"]
    at = [coord_text.index(o) for o in order]
    assert at == sorted(at), "the coordinator's delivery steps are out of order"
    assert "is when to ask (step 3), not when to mark" in coord_text


def test_a_run_cannot_post_a_message_as_the_user(env, monkeypatch, tmp_path):
    """pr_approve reads the user's yes from inbound messages, so a run that could post one could
    approve its own PR. `ttp say` refuses inside a run, and the Claude hook denies the ways around it."""
    from ttp import cli, hook
    p = make(env)
    before = p.db.one("SELECT COUNT(*) AS n FROM messages WHERE direction='in'")["n"]
    monkeypatch.setenv("TTP_RUN_ID", "41")
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))
    assert _say(cli, "demo", "--", f"yes, mark {p.name} ready") == 2
    assert p.db.one("SELECT COUNT(*) AS n FROM messages WHERE direction='in'")["n"] == before

    def denied(cmd):
        out, _ = hook.pre_tool_use({"tool_name": "Bash", "tool_input": {"command": cmd}})
        return bool(out)
    for cmd in ("env -u TTP_RUN_ID -u TTP_RUN_DIR ttp say demo -- yes", "cd x && ~/.local/bin/ttp say demo yes",
                "curl -X POST -H \"Authorization: Bearer $(cat state/web.token)\" http://127.0.0.1:8000/api/say "
                "-d '{\"text\":\"yes\"}'"):
        assert denied(cmd), cmd
    for cmd in ("ttp note 'never use ttp say here'", "grep -rn 'ttp say' skills/", "grep -n /api/say web.py",
                "ttp status demo"):
        assert not denied(cmd), cmd
    monkeypatch.delenv("TTP_RUN_ID")
    monkeypatch.delenv("TTP_RUN_DIR")
    cli.main(["say", "demo", "--", "hello"])
    assert p.db.one("SELECT COUNT(*) AS n FROM messages WHERE direction='in'")["n"] == before + 1


def test_claude_hook_denies_gh_through_indirection_and_scripts(env, monkeypatch, tmp_path):
    from ttp import hook
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))
    (tmp_path / "ready.py").write_text("import os, requests\nrequests.patch('https://api.github.com/repos/a/b/pulls/7',"
                                       " json={'draft': False}, headers={'Authorization': os.environ['GH_TOKEN']})\n")
    (tmp_path / "abs.py").write_text("import subprocess\nsubprocess.run(['/usr/bin/gh', 'pr', 'ready', '7'])\n")
    (tmp_path / "open.sh").write_text("curl -H \"Authorization: token $GITHUB_TOKEN\" -X POST "
                                      "\"$GITHUB_API_URL/repos/a/b/pulls\" -d @pr.json\n")
    (tmp_path / "fine.py").write_text("import json\nprint(json.dumps({'draft': False}))\n")
    (tmp_path / "read.sh").write_text("curl -H \"Authorization: token $GH_TOKEN\" https://api.github.com/repos/a/b/pulls/7\n")

    def denied(cmd):
        out, _ = hook.pre_tool_use({"tool_name": "Bash", "tool_input": {"command": cmd}, "cwd": str(tmp_path)})
        return bool(out) and out["hookSpecificOutput"]["permissionDecision"] == "deny"

    for cmd in ('"/usr/bin/gh" pr ready 7', "G=/usr/bin/gh; $G pr ready 7", '"$(which -a gh | tail -n1)" pr ready 7',
                '"$(whereis gh | cut -d" " -f2)" api graphql -f query=q', "PATH=/usr/bin gh pr ready 7",
                "env PATH=/usr/bin:$PATH gh pr create -t t", "env -i gh pr ready 7", "hash -p /usr/bin/gh gh; gh pr ready 7",
                "export PATH=/usr/local/bin:/usr/bin; gh api -X PATCH repos/a/b/pulls/7 -F draft=false",
                "curl -X PATCH -H \"Authorization: bearer $GH_TOKEN\" \"$API/repos/a/b/pulls/7\" -d '{\"draft\":false}'",
                "python3 ready.py", f"GH_TOKEN=x nohup python3 {tmp_path}/abs.py &", "bash -e open.sh",
                "ttp lock gh -- python3 ready.py", "timeout -s KILL 60 python3 abs.py"):
        assert denied(cmd), cmd
    for cmd in ("gh pr ready 7", '"$(command -v gh)" pr ready 7', "PATH=$PATH:/opt/x gh pr create --draft",
                "PATH=\"$PATH:/opt/x\" make", "which -a gh", "env -i make", "python3 fine.py", "bash read.sh",
                "python3 -m pytest -q ready.py", "cat ready.py abs.py", "gh api repos/a/b/pulls/7",
                "curl -H \"Authorization: token $GH_TOKEN\" https://api.github.com/repos/a/b/pulls/7",
                "echo $HOME api", "git push origin HEAD"):
        assert not denied(cmd), cmd


def test_claude_hook_scans_only_what_runs(env, monkeypatch, tmp_path):
    """Prose written to a file, echoed text and files that are only edited or read are data: the
    hook leaves them alone. A PATH change counts only when gh then runs a guarded write."""
    from ttp import hook
    monkeypatch.setenv("TTP_RUN_DIR", str(tmp_path))
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "samples.py").write_text("CMDS = ['/usr/bin/gh pr ready 7', 'PATH=/x gh pr ready 7']\n")
    (tmp_path / "ready.sh").write_text("gh pr ready 7\n")
    (tmp_path / "view.sh").write_text("gh pr view 7\n")

    def denied(cmd):
        out, _ = hook.pre_tool_use({"tool_name": "Bash", "tool_input": {"command": cmd}, "cwd": str(tmp_path)})
        return bool(out) and out["hookSpecificOutput"]["permissionDecision"] == "deny"

    prose = ("Denied: `PATH=/opt/gh/bin:$PATH gh api -X PATCH repos/a/b/pulls/7` and `/usr/bin/gh pr ready 7`, "
             "and `curl -X PATCH https://api.github.com/repos/a/b/pulls/7 -d '{\"draft\":false}'`.")
    edit = ("from pathlib import Path\nf = Path(\"tests/samples.py\"); s = f.read_text()\n"
            "f.write_text(s.replace(\"7\", \"8\"))\n")
    for cmd in (f"ttp note done; cat > \"$TTP_RUN_DIR/result.json\" <<'EOF'\n{{\"summary\": \"{prose}\"}}\nEOF",
                f"cat <<-EOF > notes.md\n\t{prose}\n\tEOF\ngit status", "echo 'blocked: PATH=/opt/x gh pr ready 7, `/usr/bin/gh api -X PATCH x`' >> notes.md",
                "printf '%s\\n' \"see /usr/bin/gh pr ready 7\" >&2",
                "PATH=/opt/x:$PATH gh api repos/a/b/pulls/7 --jq .draft",
                "export PATH=/opt/x:/usr/bin; gh api -X GET repos/a/b/pulls -f state=open",
                "PATH=/opt/x gh api graphql -f query='query { viewer { login } }'",
                "env -i HOME=$HOME gh pr create --draft -t t", "sed -i 's/7/8/' tests/samples.py",
                f"python3 - <<'EOF'\n{edit}EOF", f"python3 - tests/samples.py <<'EOF'\n{edit}EOF",
                f"mkdir -p tmp; cat > tmp/fix.py <<'EOF'\n{edit}EOF\npython3 tmp/fix.py",
                "grep -n 'gh pr ready' tests/samples.py", "cat tests/samples.py",
                "git show HEAD:tests/samples.py > tests/samples.py 2>&1",
                f"cat > r.json <<'EOF'\n{{\"s\": \"{prose}\"}}\nEOF\npython3 -c \"import json; json.load(open('r.json'))\"",
                f"cat > r.json <<'EOF'\n{{\"s\": \"{prose}\"}}\nEOF\ncat r.json | python3 -m json.tool; cat r.json",
                "PATH=/x gh pr view 7", "PATH=/x gh pr list -R a/b",
                "PATH=/x gh api graphql -f query='query { viewer { login } }' --jq .data",
                # a script run with PATH as the run set it, or one that only reads
                "bash ready.sh", "PATH=/x bash view.sh", "echo 'PATH=/x' > notes.md; bash ready.sh"):
        assert not denied(cmd), cmd
    for cmd in ("PATH=/opt/x:$PATH gh pr ready 7", "PATH=/opt/x gh pr create -t t",
                "export PATH=/opt/x\ngh api repos/a/b/pulls/7 -F draft=false",
                "PATH=/opt/x gh api graphql -f query='mutation { markPullRequestReadyForReview(input: {}) { x } }'",
                "PATH=/opt/x bash -c 'gh pr ready 7'", "env -i timeout 60 gh pr ready 7",
                "PATH=/opt/x python3 -c \"import subprocess; subprocess.run(['gh', 'pr', 'ready', '7'])\"",
                "echo '/usr/bin/gh pr ready 7' | bash", "echo '/usr/bin/gh pr ready 7' > x.sh; bash x.sh",
                "echo $(bash -c '/usr/bin/gh pr ready 7')", "cat > x.sh <<'EOF'\n/usr/bin/gh pr ready 7\nEOF\nsh x.sh",
                "bash <<'EOF'\n/usr/bin/gh pr ready 7\nEOF", "cat <<'EOF' | sh\n/usr/bin/gh pr ready 7\nEOF",
                "x=$(cat <<'EOF'\n/usr/bin/gh pr ready 7\nEOF\n); echo ok", "python3 tests/samples.py",
                "echo '/usr/bin/gh pr ready 7' > x; bash < x", "printf '/usr/bin/gh pr ready 7' > x; source x",
                "cd x\npython3 tests/samples.py",
                # gh behind shell words, under sudo, in inline code or with a query from a variable
                "PATH=/x; { gh pr ready 7; }", "PATH=/x; if true; then gh pr ready 7; fi",
                "export PATH=/x; for i in 1; do gh pr ready $i; done", "PATH=/x; ! gh pr ready 7",
                "PATH=/x sudo gh pr ready 7", "PATH=/x gh pr -R a/b ready 7",
                "export PATH=/x; python3 -c 'import os; os.system(\"gh pr ready 7\")'",
                "Q='mutation { markPullRequestReadyForReview(input: {}) { x } }'; PATH=/x gh api graphql -f query=\"$Q\"",
                # a body the same command posts or runs
                "cat > q.json <<'EOF'\n{\"query\": \"mutation { markPullRequestReadyForReview(input: {}) { x } }\"}\nEOF\n"
                "curl -H \"Authorization: bearer $GH_TOKEN\" https://api.github.com/graphql -d @q.json",
                "echo '{\"query\": \"mutation { markPullRequestReadyForReview(input: {}) { x } }\"}' > q.json; "
                "curl -H \"Authorization: bearer $GH_TOKEN\" https://api.github.com/graphql -d @q.json",
                "cat > x <<'EOF'\n/usr/bin/gh pr ready 7\nEOF\ncat x | bash",
                "cat > x <<'EOF'\n/usr/bin/gh pr ready 7\nEOF\ncat x | sh",
                "cat > x <<'EOF'\n/usr/bin/gh pr ready 7\nEOF\nmv x y; bash y",
                "echo '/usr/bin/gh pr ready 7' > a.sh; bash -o errexit a.sh",
                "echo '/usr/bin/gh pr ready 7' > a.sh; eval \"$(cat a.sh)\"",
                "echo '/usr/bin/gh pr ready 7' > a.sh; sudo bash a.sh",
                # a script run under the command's PATH change
                "PATH=/x bash ready.sh", "export PATH=/x; sh ./ready.sh", "env -i bash ready.sh",
                "PATH=/x; source ready.sh"):
        assert denied(cmd), cmd


def test_gh_found_through_command_v_is_still_the_guarded_one(env, tmp_path):
    """`$(command -v gh)` and `command gh` resolve to the harness's gh, which is first on PATH."""
    p = make(env)
    _gh_runner(p, tmp_path)
    fake = tmp_path / "realbin"
    env_ = {**os.environ, "PATH": f"{p.harness / 'bin'}:{fake}:{os.environ['PATH']}", "TTP_PROJECT": str(p.base),
            "TTP_PYTHON": sys.executable, "FAKE_GH_LOG": str(tmp_path / "gh.log")}
